/**
 * Gerbang akses kartu dashboard di portal.
 *
 * Satu berkas supaya Home (menentukan section muncul atau tidak) dan
 * DashboardCarousel (menentukan kartu mana yang dirender) tidak bisa berbeda
 * pendapat. Tiap daftar role di sini SENGAJA menyalin gerbang di server; kalau
 * server berubah, ubah juga di sini agar kartunya tidak pernah menjadi pintu
 * yang justru ditolak saat diketuk.
 */

// Server: juragan/api/portal/realisasi_collection.py
// Di luar keempat role ini hanya user Administrator yang boleh — SENGAJA bukan
// System Manager, karena servernya pun hanya mengenali Administrator.
export const REALISASI_COLLECTION_ROLES = [
	'Director',
	'Manager Finance',
	'Manager Coll',
	'Head Field Coll',
	'Field Coll',
]

// Server: PORTAL_ROLES pada juragan/api/portal/sales_dashboard.py, yaitu
// ROLE_YANG_DIIZINKAN milik page dikurangi Admin OPS. Admin OPS sengaja hanya
// ditutup DI PORTAL; halaman desk-nya tetap terbuka untuk role itu.
export const SALES_DASHBOARD_ROLES = [
	'Director',
	'Credit Analyst',
	'Manager Finance',
	'Manager Coll',
	'Manager Ops',
	'Manager Internal Audit',
	'System Manager',
	'Pimpinan Cabang',
]

// Server: assert_cmo_dashboard_access pada
// juragan/juragan/page/cmo_sales_dashboard/permissions.py — role CMO saja.
// Tidak ada pengecualian Administrator di sini: Administrator memang memegang
// role CMO lewat frappe.get_roles, jadi kartunya ikut tampil untuknya.
export const CMO_DASHBOARD_ROLES = ['CMO']

export function bolehCmoDashboard(user, roles = []) {
	return CMO_DASHBOARD_ROLES.some((r) => roles.includes(r))
}

// Server: _assert_cmo pada
// juragan/juragan/page/cmo_dashboard_fid_fpd/cmo_dashboard_fid_fpd_api.py —
// role CMO saja, sama dengan CMO Sales Dashboard.
export function bolehCmoFidFpd(user, roles = []) {
	return CMO_DASHBOARD_ROLES.some((r) => roles.includes(r))
}

export function bolehRealisasiCollection(user, roles = []) {
	return user === 'Administrator' || REALISASI_COLLECTION_ROLES.some((r) => roles.includes(r))
}

export function bolehSalesDashboard(user, roles = []) {
	return user === 'Administrator' || SALES_DASHBOARD_ROLES.some((r) => roles.includes(r))
}

// Server: ALLOWED_ROLES pada
// juragan/juragan/page/fid_fpd_dashboard/fid_fpd_dashboard_api.py
export const FID_FPD_ROLES = [
	'Director',
	'Credit Analyst',
	'Manager Finance',
	'Manager Coll',
	'Manager Ops',
	'Manager Internal Audit',
	'System Manager',
	'Pimpinan Cabang',
]

export function bolehFidFpdDashboard(user, roles = []) {
	return FID_FPD_ROLES.some((r) => roles.includes(r))
}

/** True bila user berhak atas setidaknya satu kartu dashboard. */
export function punyaDashboard(user, roles = []) {
	return (
		bolehRealisasiCollection(user, roles) ||
		bolehSalesDashboard(user, roles) ||
		bolehCmoDashboard(user, roles) ||
		bolehCmoFidFpd(user, roles) ||
		bolehFidFpdDashboard(user, roles)
	)
}
