<template>
	<Transition name="offline-fade">
		<div
			v-if="!isOnline"
			class="fixed inset-0 z-[90] flex flex-col items-center justify-center bg-ui-surface-gray-50 px-8 text-center"
			style="
				padding-top: env(safe-area-inset-top);
				padding-bottom: env(safe-area-inset-bottom);
			"
			role="alert"
			aria-live="assertive"
		>
			<!-- Ikon dalam lingkaran lembut -->
			<div class="relative mb-6">
				<span
					class="absolute inset-0 animate-ping rounded-full bg-primary/10"
					aria-hidden="true"
				/>
				<div
					class="relative flex h-24 w-24 items-center justify-center rounded-full bg-ui-surface shadow-sm ring-1 ring-ui-line-gray-100"
				>
					<svg
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						class="h-11 w-11 text-primary"
						fill="none"
						stroke="currentColor"
						stroke-width="1.8"
						stroke-linecap="round"
						stroke-linejoin="round"
					>
						<path d="M2 2 22 22" />
						<path d="M8.5 16.5a5 5 0 0 1 7 0" />
						<path d="M2 8.82a15 15 0 0 1 4.17-2.65" />
						<path d="M10.66 5c4.01-.36 8.14.9 11.34 3.76" />
						<path d="M16.85 11.25a10 10 0 0 1 2.22 1.68" />
						<path d="M5 13a10 10 0 0 1 5.24-2.76" />
						<line x1="12" y1="20" x2="12.01" y2="20" />
					</svg>
				</div>
			</div>

			<h1 class="text-xl font-bold text-ui-ink-gray-900">Tidak Ada Koneksi</h1>
			<p class="mt-2 max-w-xs text-sm leading-relaxed text-ui-ink-gray-500">
				Sepertinya jaringanmu sedang bermasalah. Periksa koneksi internet lalu coba lagi.
			</p>

			<button
				type="button"
				:disabled="checking"
				class="mt-7 inline-flex items-center gap-2 rounded-xl bg-primary px-7 py-3 text-sm font-semibold text-ui-onPrimary shadow-sm transition hover:bg-primary/90 active:scale-95 disabled:opacity-60"
				@click="retry"
			>
				<svg
					xmlns="http://www.w3.org/2000/svg"
					viewBox="0 0 24 24"
					class="h-4 w-4"
					:class="{ 'animate-spin': checking }"
					fill="none"
					stroke="currentColor"
					stroke-width="2.2"
					stroke-linecap="round"
					stroke-linejoin="round"
				>
					<path d="M3 12a9 9 0 0 1 9-9 9.75 9.75 0 0 1 6.74 2.74L21 8" />
					<path d="M21 3v5h-5" />
					<path d="M21 12a9 9 0 0 1-9 9 9.75 9.75 0 0 1-6.74-2.74L3 16" />
					<path d="M8 16H3v5" />
				</svg>
				{{ checking ? 'Menyambungkan…' : 'Coba Lagi' }}
			</button>

			<p class="mt-4 text-xs text-ui-ink-gray-400">
				Akan tersambung otomatis saat koneksi kembali.
			</p>
		</div>
	</Transition>
</template>

<script setup>
import { ref, onMounted, onUnmounted } from 'vue'

const isOnline = ref(typeof navigator === 'undefined' ? true : navigator.onLine)
const checking = ref(false)

function goOnline() {
	isOnline.value = true
	checking.value = false
}
function goOffline() {
	isOnline.value = false
}

function retry() {
	if (checking.value) return
	// Kalau sudah online lagi → muat ulang agar data ter-refresh.
	if (navigator.onLine) {
		checking.value = true
		window.location.reload()
		return
	}
	// Masih offline → beri umpan balik singkat lalu berhenti.
	checking.value = true
	setTimeout(() => {
		checking.value = false
		if (navigator.onLine) goOnline()
	}, 1200)
}

onMounted(() => {
	window.addEventListener('online', goOnline)
	window.addEventListener('offline', goOffline)
})
onUnmounted(() => {
	window.removeEventListener('online', goOnline)
	window.removeEventListener('offline', goOffline)
})
</script>

<style scoped>
.offline-fade-enter-active,
.offline-fade-leave-active {
	transition: opacity 0.25s ease;
}
.offline-fade-enter-from,
.offline-fade-leave-to {
	opacity: 0;
}
</style>
