/**
 * Ambil file biner (gambar/PDF) lewat HTTP NATIVE (plugin CapacitorHttp).
 *
 * Kenapa: file di produksi dilayani nginx/statis (`/files`, `/private/files`,
 * `/assets`) yang TIDAK mengirim header CORS. Dari bundel lokal (origin
 * `capacitor://localhost`) fetch biasa ke sana diblokir CORS → "Load failed".
 * Permintaan native tidak tunduk pada CORS browser, jadi file bisa diambil.
 * Token dikirim sebagai header Authorization (untuk file privat).
 *
 * Hanya untuk native. Di web, kode pemanggil tetap pakai fetch biasa.
 */
import { API_BASE, getToken } from './mobile'

function getCapacitorHttp() {
	return (
		(typeof window !== 'undefined' &&
			window.Capacitor &&
			window.Capacitor.Plugins &&
			window.Capacitor.Plugins.CapacitorHttp) ||
		null
	)
}

function base64ToUint8Array(b64) {
	const binary = atob(b64)
	const len = binary.length
	const bytes = new Uint8Array(len)
	for (let i = 0; i < len; i++) bytes[i] = binary.charCodeAt(i)
	return bytes
}

function headerValue(headers, name) {
	if (!headers) return ''
	const lower = name.toLowerCase()
	for (const k of Object.keys(headers)) {
		if (k.toLowerCase() === lower) return headers[k]
	}
	return ''
}

/**
 * @returns {Promise<{bytes: Uint8Array, contentType: string}>}
 */
export async function fetchBinaryNative(url) {
	const Http = getCapacitorHttp()
	if (!Http) throw new Error('CapacitorHttp tidak tersedia')

	let u = url
	if (u && u.charAt(0) === '/') u = API_BASE + u

	const headers = {}
	const tok = getToken()
	if (tok) headers.Authorization = 'token ' + tok

	const res = await Http.get({ url: u, headers, responseType: 'blob' })
	if (res.status >= 400) throw new Error('HTTP ' + res.status)

	const contentType = headerValue(res.headers, 'content-type') || 'application/octet-stream'
	// responseType 'blob' → res.data berupa string base64.
	const bytes = base64ToUint8Array(res.data || '')
	return { bytes, contentType }
}
