const VERSION = 1
const PREFIX = 'juragan.portal'

export const STORAGE_TTL = Object.freeze({
	DAY: 24 * 60 * 60 * 1000,
	DRAFT: 30 * 24 * 60 * 60 * 1000,
	DASHBOARD_CACHE: 24 * 60 * 60 * 1000,
	LINK_TITLE_CACHE: 7 * 24 * 60 * 60 * 1000,
	PASSWORD_RESET: 24 * 60 * 60 * 1000,
})

function encoded(value) {
	return encodeURIComponent(String(value || 'anon'))
}

export function portalStorageKey(kind, user, scope) {
	return `${PREFIX}.${kind}.v${VERSION}:${encoded(user)}:${encoded(scope)}`
}

function browserStorage(kind) {
	if (typeof window === 'undefined') return null
	try {
		return kind === 'session' ? window.sessionStorage : window.localStorage
	} catch {
		return null
	}
}

function isPlainObject(value) {
	return value !== null && typeof value === 'object' && !Array.isArray(value)
}

// Ambil hanya field yang dikenal oleh defaults dan pertahankan tipe dasarnya.
// Ini sekaligus membuang field lama setelah bentuk state halaman berubah.
export function mergeStoredDefaults(defaults, saved) {
	if (Array.isArray(defaults)) return Array.isArray(saved) ? [...saved] : [...defaults]
	if (!isPlainObject(defaults)) {
		return typeof saved === typeof defaults ? saved : defaults
	}
	const source = isPlainObject(saved) ? saved : {}
	const result = {}
	for (const [key, fallback] of Object.entries(defaults)) {
		result[key] = mergeStoredDefaults(fallback, source[key])
	}
	return result
}

function safeRemove(storage, key) {
	try {
		storage?.removeItem(key)
	} catch {
		// Storage dapat diblokir oleh browser/WebView. State reaktif tetap berjalan.
	}
}

export function readPortalState(kind, user, scope, defaults, options = {}) {
	const storage = options.storage || browserStorage(kind)
	const key = portalStorageKey(kind, user, scope)
	const fallback = () => (defaults === undefined ? null : mergeStoredDefaults(defaults, {}))
	try {
		const raw = storage?.getItem(key)
		if (!raw) return fallback()
		const envelope = JSON.parse(raw)
		if (
			!isPlainObject(envelope) ||
			envelope.v !== VERSION ||
			!Number.isFinite(Number(envelope.savedAt)) ||
			!('expiresAt' in envelope) ||
			!('data' in envelope)
		) {
			safeRemove(storage, key)
			return fallback()
		}
		const expiresAt = envelope.expiresAt === null ? null : Number(envelope.expiresAt)
		if (
			(expiresAt !== null && !Number.isFinite(expiresAt)) ||
			(expiresAt !== null && expiresAt <= (options.now ?? Date.now()))
		) {
			safeRemove(storage, key)
			return fallback()
		}
		return defaults === undefined
			? JSON.parse(JSON.stringify(envelope.data))
			: mergeStoredDefaults(defaults, envelope.data)
	} catch {
		safeRemove(storage, key)
		return fallback()
	}
}

export function writePortalState(kind, user, scope, data, options = {}) {
	const storage = options.storage || browserStorage(kind)
	const now = options.now ?? Date.now()
	const ttl = Number(options.ttlMs) || 0
	try {
		if (!storage) return false
		const envelope = {
			v: VERSION,
			savedAt: now,
			expiresAt: ttl > 0 ? now + ttl : null,
			// JSON round-trip melepas Vue Proxy dan mencegah referensi array ikut berubah.
			data: JSON.parse(JSON.stringify(data)),
		}
		storage.setItem(portalStorageKey(kind, user, scope), JSON.stringify(envelope))
		return true
	} catch {
		return false
	}
}

export function removePortalState(kind, user, scope, options = {}) {
	safeRemove(options.storage || browserStorage(kind), portalStorageKey(kind, user, scope))
}

export function removeLegacyStorageKey(key, options = {}) {
	safeRemove(options.storage || browserStorage('local'), key)
}

export function removeLegacyStoragePrefix(prefix, options = {}) {
	clearMatching(options.storage || browserStorage(options.kind || 'local'), (key) =>
		key.startsWith(prefix),
	)
}

function clearMatching(storage, predicate) {
	try {
		const keys = []
		for (let index = 0; index < storage.length; index += 1) {
			const key = storage.key(index)
			if (key && predicate(key)) keys.push(key)
		}
		keys.forEach((key) => storage.removeItem(key))
	} catch {
		// Logout tidak boleh gagal hanya karena storage tidak tersedia.
	}
}

export function clearPortalUserStorage(user, options = {}) {
	const userToken = `:${encoded(user)}:`
	const session = options.sessionStorage || browserStorage('session')
	const local = options.localStorage || browserStorage('local')
	clearMatching(
		session,
		(key) => key.startsWith(`${PREFIX}.session.`) && key.includes(userToken),
	)
	clearMatching(
		local,
		(key) =>
			(key.startsWith(`${PREFIX}.draft.`) || key.startsWith(`${PREFIX}.cache.`)) &&
			key.includes(userToken),
	)
}
